#include <stdio.h>

static int from[200000], to[200000];
static int start[100002], fill[100001], adj[400000];
static int component[100001], stack[100000];

int main(void) {
    int vertices, edges;
    if (scanf("%d %d", &vertices, &edges) != 2 || vertices < 1 || vertices > 100000 || edges > 200000) {
        return 0;
    }
    for (int i = 0; i < edges; i++) {
        scanf("%d %d", &from[i], &to[i]);
        start[from[i] + 1]++;
        start[to[i] + 1]++;
    }
    for (int v = 1; v <= vertices + 1; v++) {
        start[v] += start[v - 1];
    }
    for (int v = 1; v <= vertices; v++) {
        fill[v] = start[v];
    }
    for (int i = 0; i < edges; i++) {
        adj[fill[from[i]]++] = to[i];
        adj[fill[to[i]]++] = from[i];
    }
    int count = 0;
    for (int s = 1; s <= vertices; s++) {
        if (component[s] != 0) {
            continue;
        }
        count++;
        int size = 0;
        component[s] = count;
        stack[size++] = s;
        while (size > 0) {
            int u = stack[--size];
            for (int k = start[u]; k < start[u + 1]; k++) {
                int v = adj[k];
                if (component[v] == 0) {
                    component[v] = count;
                    stack[size++] = v;
                }
            }
        }
    }
    printf("%d\n", count);
    for (int v = 1; v <= vertices; v++) {
        printf(v < vertices ? "%d " : "%d\n", component[v]);
    }
    return 0;
}

