#include <stdio.h>

static int from[5000], to[5000];
static int start[1002], fill[1001], adj[5000];
static int color[1001];

static bool dfs(int u) {
    color[u] = 1;
    for (int k = start[u]; k < start[u + 1]; k++) {
        int v = adj[k];
        if (color[v] == 1) {
            return true;
        }
        if (color[v] == 0 && dfs(v)) {
            return true;
        }
    }
    color[u] = 2;
    return false;
}

int main(void) {
    int vertices, edges;
    if (scanf("%d %d", &vertices, &edges) != 2 || vertices < 1 || vertices > 1000 || edges > 5000) {
        return 0;
    }
    for (int i = 0; i < edges; i++) {
        scanf("%d %d", &from[i], &to[i]);
        start[from[i] + 1]++;
    }
    for (int v = 1; v <= vertices + 1; v++) {
        start[v] += start[v - 1];
    }
    for (int v = 1; v <= vertices; v++) {
        fill[v] = start[v];
    }
    for (int i = 0; i < edges; i++) {
        adj[fill[from[i]]++] = to[i];
    }
    bool cycle = false;
    for (int u = 1; u <= vertices && !cycle; u++) {
        if (color[u] == 0) {
            cycle = dfs(u);
        }
    }
    printf("%s\n", cycle ? "да" : "нет");
    return 0;
}

