static char map[100][102];
static int rows, cols;

static void flood(int r, int c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols || map[r][c] != '#') {
        return;
    }
    flood(r - 1, c);
    flood(r + 1, c);
    flood(r, c - 1);
    flood(r, c + 1);
    map[r][c] = '*';
}

int main(void) {
    if (scanf("%d %d", &rows, &cols) != 2 || rows < 1 || rows > 100 || cols < 1 || cols > 100) {
        return 0;
    }
    for (int r = 0; r < rows; r++) {
        scanf("%101s", map[r]);
    }
    int islands = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (map[r][c] == '#') {
                flood(r, c);
                islands++;
            }
        }
    }
    printf("%d\n", islands);
    return 0;
}

