#include <stdio.h>

static bool adj[1001][1001];
static int color[1001], order[1000], count;
static int vertices;
static bool cycle;

static void dfs(int u) {
    color[u] = 1;
    for (int v = 1; v <= vertices && !cycle; v++) {
        if (!adj[u][v]) {
            continue;
        }
        if (color[v] == 1) {
            cycle = true;
        } else if (color[v] == 0) {
            dfs(v);
        }
    }
    color[u] = 2;
    order[count++] = u;
}

int main(void) {
    int edges;
    if (scanf("%d %d", &vertices, &edges) != 2 || vertices < 1 || vertices > 1000) {
        return 0;
    }
    for (int i = 0; i < edges; i++) {
        int u, v;
        if (scanf("%d %d", &u, &v) != 2) {
            break;
        }
        adj[u][v] = true;
    }
    for (int u = 1; u <= vertices && !cycle; u++) {
        if (color[u] == 0) {
            dfs(u);
        }
    }
    if (cycle) {
        printf("цикл\n");
        return 0;
    }
    for (int i = count - 1; i >= 0; i--) {
        printf(i > 0 ? "%d " : "%d\n", order[i]);
    }
    return 0;
}

