    color[u] = 1;
    for (int v = 0; v < 5; v++) {
        if (adj[u][v] && color[v] == 0) {
            dfs(v);
        }
    }
    color[u] = 2;
    order[count++] = u;
}

int main(void) {
    adj[0][2] = adj[1][2] = adj[2][3] = adj[1][4] = 1;
    for (int u = 0; u < 5; u++) {
        if (color[u] == 0) {
            dfs(u);
        }
    }
    for (int i = count - 1; i >= 0; i--) {
        printf("%d ", order[i]);
    }
    printf("\n");
    return 0;
}
